css:
:root:not(.dark) [data-right-panel-surface-content], :root:not(.dark) [data-pull-request-summary-scroll], :root:not(.dark) [data-thread-details-card], :root:not(.dark) [data-pull-request-summary-section] > :first-child { background: #f8fafd !important; }
[data-pull-request-summary-section] > :first-child { padding-bottom: 8px !important; }
[data-pr-description] { border: 1px solid rgba(0, 0, 0, 0.08) !important; border-radius: 8px !important; padding: 12px 14px !important; }
.dark [data-pr-description] { border-color: rgba(255, 255, 255, 0.1) !important; }
:root:not(.dark) [data-pr-description] { background: #ffffff !important; }
:root:not(.dark) [data-slot="popover-popup"], :root:not(.dark) [data-slot="tooltip-popup"], :root:not(.dark) [data-slot="menu-popup"] { background: #ffffff !important; }
.dark [data-right-panel-surface-content] { background: rgba(255, 255, 255, 0.04) !important; }
/* Diff panel: show the Files tree on the left. The app has no setting for this; the handle is moved to the inner edge, but the app still resizes as if the pane were on the right, so dragging toward the diff shrinks it. */
aside[aria-label="File explorer"] { order: -1 !important; border-left-width: 0 !important; border-right: 1px solid var(--border) !important; }
aside[aria-label="File explorer"] > [role="separator"] { left: auto !important; right: 0 !important; }
